 static void SetQuoteItem(DataTable cart,DataRow editing,DataRow p,decimal q,decimal price,decimal discount){if(p==null)throw new Exception("Selecione o produto.");if(q<=0||q!=Math.Truncate(q)||price<0||discount<0||discount>100)throw new Exception("Confira quantidade, preço e desconto.");decimal final=Store.Money(price*(1-discount/100));if(editing==null)cart.Rows.Add(p["Id"],p["Código"],p["Nome"],q,price,discount,final,Store.Money(q*final));else{editing["Produto"]=p["Id"];editing["Código"]=p["Código"];editing["Descrição"]=p["Nome"];editing["Quantidade"]=q;editing["Preço original"]=price;editing["Desconto %"]=discount;editing["Preço"]=final;editing["Total"]=Store.Money(q*final);}}
